// Synthetic ground-truth corpus (report §12.1 / Common Setup).
// Every shape is generated by stroking a KNOWN centerline, so both the true
// centerline error and the reconstruction error can be measured.
//
// Cases 1-20 are the report's list verbatim; 21-22 add the acute joins that
// Track 1's brief calls out explicitly alongside the 90-degree ones.

import {
  L, A, strokeToOutline, unionPathDs, taperedStroke, noisifyPathD, sampleCenterline,
} from './stroker.mjs';

const VB = { x: 0, y: 0, w: 300, h: 200 };
const W = 20;

const deg = (d) => d;

function capsule(p0, p1, w = W, opts = {}) {
  const pieces = [L(p0, p1)];
  return { pieces, ...strokeToOutline(pieces, w, opts) };
}

function build() {
  const cases = [];
  const add = (num, name, spec) => cases.push({ num, name, id: `${String(num).padStart(2, '0')}-${name}`, width: W, viewBox: VB, ...spec });

  /* 1 */ {
    const p = [L([50, 100], [250, 100])];
    add(1, 'horizontal-line', { truth: [p], elements: [strokeToOutline(p, W)] });
  }
  /* 2 */ {
    const p = [L([50, 165], [250, 45])];
    add(2, 'diagonal-line', { truth: [p], elements: [strokeToOutline(p, W)] });
  }
  /* 3 */ {
    const p = [A(150, 180, 110, deg(-170), deg(-10))];
    add(3, 'circular-arc', { truth: [p], elements: [strokeToOutline(p, W)] });
  }
  /* 4 */ {
    const p = [A(105, 100, 50, 180, 360), A(205, 100, 50, 180, 0)];
    add(4, 's-curve', { truth: [p], elements: [strokeToOutline(p, W)] });
  }
  /* 5 */ {
    const p = [L([80, 40], [80, 110]), A(110, 110, 30, 180, 0), L([140, 110], [140, 40])];
    add(5, 'tight-u-curve', { truth: [p], elements: [strokeToOutline(p, W)] });
  }
  /* 6 */ {
    const p = [A(150, 100, 62, 0, 360)];
    add(6, 'closed-loop', { truth: [p], elements: [strokeToOutline(p, W, { closed: true })] });
  }
  /* 7 */ {
    const p = [L([60, 100], [240, 100])];
    add(7, 'round-cap', { truth: [p], elements: [strokeToOutline(p, W, { cap: 'round' })] });
  }
  /* 8 */ {
    const p = [L([60, 100], [240, 100])];
    add(8, 'butt-cap', { truth: [p], elements: [strokeToOutline(p, W, { cap: 'butt' })], capType: 'butt' });
  }
  /* 9 */ {
    const p = [L([60, 100], [240, 100])];
    add(9, 'square-cap', { truth: [p], elements: [strokeToOutline(p, W, { cap: 'square' })], capType: 'square' });
  }
  /* 10-12: 90-degree joins */
  for (const [num, join] of [[10, 'round'], [11, 'bevel'], [12, 'miter']]) {
    const p = [L([60, 40], [60, 160]), L([60, 160], [240, 160])];
    add(num, `${join}-join-90`, { truth: [p], elements: [strokeToOutline(p, W, { join })], joinType: join });
  }
  /* 13 */ {
    const a = [L([50, 40], [250, 160])];
    const b = [L([50, 160], [250, 40])];
    add(13, 'x-crossing-separate', {
      truth: [a, b],
      elements: [strokeToOutline(a, W), strokeToOutline(b, W)],
    });
  }
  /* 14 */ {
    const a = [L([50, 40], [250, 160])];
    const b = [L([50, 160], [250, 40])];
    const u = unionPathDs([strokeToOutline(a, W).d, strokeToOutline(b, W).d]);
    add(14, 'x-crossing-unioned', { truth: [a, b], elements: [u], expect: 'crossing ambiguity' });
  }
  /* 15 */ {
    const a = [L([50, 60], [250, 60])];
    const b = [L([150, 60], [150, 185])];
    const u = unionPathDs([strokeToOutline(a, W).d, strokeToOutline(b, W).d]);
    add(15, 't-junction', { truth: [a, b], elements: [u] });
  }
  /* 16 */ {
    const legs = [
      [L([150, 100], [60, 40])],
      [L([150, 100], [240, 40])],
      [L([150, 100], [150, 190])],
    ];
    const u = unionPathDs(legs.map((p) => strokeToOutline(p, W).d));
    add(16, 'y-junction', { truth: legs, elements: [u] });
  }
  /* 17 */ {
    const a = [L([50, 89], [250, 89])];
    const b = [L([50, 110], [250, 110])];
    add(17, 'near-parallel', {
      truth: [a, b],
      elements: [strokeToOutline(a, W), strokeToOutline(b, W)],
      note: 'centre-to-centre 21 with width 20 -> 1 unit gap',
    });
  }
  /* 18 */ {
    const p = [L([50, 55], [225, 55]), L([225, 55], [95, 170]), L([95, 170], [95, 30])];
    add(18, 'self-overlap', { truth: [p], elements: [strokeToOutline(p, W)] });
  }
  /* 19 */ {
    const p = [L([50, 100], [250, 100])];
    add(19, 'variable-width', {
      truth: [p],
      elements: [taperedStroke([50, 100], [250, 100], 6, 30)],
      widthProfile: [6, 30],
    });
  }
  /* 20 */ {
    const p = [L([50, 100], [250, 100])];
    const clean = strokeToOutline(p, W);
    add(20, 'noisy-boundary', {
      truth: [p],
      elements: [{ d: noisifyPathD(clean.d, 1.2), area: clean.area }],
      expect: 'outline noise branch',
    });
  }
  /* 21-22: acute joins (Track 1 brief) */
  for (const [num, join] of [[21, 'round'], [22, 'miter']]) {
    const p = [L([250, 40], [70, 100]), L([70, 100], [250, 160])];
    add(num, `${join}-join-acute`, { truth: [p], elements: [strokeToOutline(p, W, { join })], joinType: join });
  }

  return cases;
}

export const CORPUS = build();

export function corpusSvg(c) {
  const body = c.elements.map((e, i) => `<path id="s${i}" fill="#000" d="${e.d}"/>`).join('\n');
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${VB.x} ${VB.y} ${VB.w} ${VB.h}">\n${body}\n</svg>\n`;
}

export function truthSvg(c) {
  const body = c.truth.map((pieces) => {
    const pts = sampleCenterline(pieces, 1);
    return `<path fill="none" stroke="#e00" stroke-width="1.5" d="M${pts.map((p) => `${p[0].toFixed(2)} ${p[1].toFixed(2)}`).join('L')}"/>`;
  }).join('\n');
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${VB.x} ${VB.y} ${VB.w} ${VB.h}">\n${body}\n</svg>\n`;
}

/** Ground-truth centerline points for the whole case. */
export function truthPoints(c, spacing = 0.4) {
  return c.truth.flatMap((pieces) => sampleCenterline(pieces, spacing));
}
